\title{Frozen Neural Tangent Kernel Dynamics:\\Geometric Convergence, Spectral Decay, and Architecture Universality}
\author{Aristotle}
\date{July 26, 2026}

\begin{document}
\maketitle

\begin{abstract}
We isolate the deterministic dynamical core of neural tangent kernel training on a finite dataset. A frozen empirical kernel $K$ with learning rate $\eta$ induces the residual update $r_{n+1}=(I-\eta K)r_n$. We establish a geometric residual estimate for any pointwise contractive update and deduce convergence of frozen-kernel predictions to the target whenever $I-\eta K$ is a strict contraction. On an eigendirection, the residual evolves exactly by $(1-\eta\lambda)^n$, exposing both spectral stability and the obstruction caused by kernel nullspaces. We prove that globally equal frozen kernels produce identical prediction trajectories and that equality of kernel actions only along the realized paths already suffices. Finally, if a trajectory remains in one tropical cell and the kernel is cellwise constant, then the kernel is frozen throughout that interval. These results give an architecture-independent convergence principle for lazy training without asserting parameter convergence or relying on an infinite-width limit.
\end{abstract}

\section{Introduction}

On a finite training set, a model's observable state is its prediction vector. In a regime where the parameter-to-output Jacobian remains fixed, gradient descent induces linear dynamics in this prediction space. The Gram operator of the Jacobian is the empirical neural tangent kernel (NTK), and the resulting regime is called lazy training.

This paper develops the architecture-independent mathematics of the recurrence
\[
r_{n+1}=r_n-\eta Kr_n.
\]
Strict contraction of $I-\eta K$ yields geometric convergence. Eigenvectors reveal exact modewise rates. Equality of kernel actions yields equality of trajectories, even for models with different parameterizations. A cell-invariance criterion supplies a geometric mechanism for exact kernel freezing.

The assumptions are intentionally explicit. A positive semidefinite kernel need not contract strictly: every nullspace direction is fixed by $I-\eta K$. The results concern predictions on a finite training set, not convergence of parameters or behavior on unseen inputs.

\section{Definitions and setting}

Let $E$ be a real normed vector space. The standard finite-data example is $E=\mathbb{R}^N$ with its Euclidean norm. Let $y\in E$ be the target vector and $f_n\in E$ the prediction vector after $n$ updates.

\begin{definition}[Residual and prediction]
The residual is $r_n=f_n-y$. Equivalently, $f_n=y+r_n$. Thus $r_n\to0$ if and only if $f_n\to y$.
\end{definition}

\begin{definition}[Iterated update]
For a map $S:E\to E$ and an initial vector $r_0$, define $r_{n+1}=S(r_n)$. The prediction associated with target $y$ is $f_n=y+r_n$.
\end{definition}

\begin{definition}[Frozen-kernel step]
For a linear operator $K:E\to E$ and learning rate $\eta\in\mathbb{R}$, the frozen-kernel residual update is
\[
S_{K,\eta}(r)=r-\eta Kr=(I-\eta K)r.
\]
\end{definition}

\begin{definition}[Strict contraction]
The frozen update is a strict contraction if there is $q$ with $0\le q<1$ such that
\[
\|r-\eta Kr\|\le q\|r\|
\]
for every $r\in E$.
\end{definition}

For the geometric freezing criterion, let $c:\mathbb{R}^P\to C$ assign a cell label and let $\mathcal K:\mathbb{R}^P\to\mathbb{R}^{N\times N}$ assign a kernel matrix.

\begin{definition}[Cellwise-constant kernel]
The kernel $\mathcal K$ is cellwise constant if
\[
c(\theta)=c(\theta')\quad\Longrightarrow\quad
\mathcal K(\theta)=\mathcal K(\theta')
\]
for all parameter vectors $\theta,\theta'\in\mathbb{R}^P$.
\end{definition}

\section{Contractive residual dynamics}

\begin{theorem}[Geometric residual bound]
Let $S:E\to E$ satisfy $\|S(r)\|\le q\|r\|$ for every $r\in E$, where $q\ge0$. If $r_{n+1}=S(r_n)$, then for every $n\ge0$,
\[
\|r_n\|\le q^n\|r_0\|.
\]
\end{theorem}

\begin{proof}
Induct on $n$. The assertion at $n=0$ is equality. If it holds at $n$, then
\[
\|r_{n+1}\|=\|S(r_n)\|\le q\|r_n\|
\le q\,q^n\|r_0\|=q^{n+1}\|r_0\|.
\]
\end{proof}

\begin{corollary}[Convergence under strict contraction]
Under the hypotheses of the preceding theorem, if $0\le q<1$, then $r_n\to0$.
\end{corollary}

\begin{proof}
The scalar sequence $q^n\|r_0\|$ tends to zero. The geometric residual bound and nonnegativity of the norm squeeze $\|r_n\|$ to zero.
\end{proof}

\begin{remark}[Iteration complexity]
If $0<q<1$ and $0<\delta<\|r_0\|$, then $\|r_n\|\le\delta$ is guaranteed whenever
\[
n\ge \frac{\log(\delta/\|r_0\|)}{\log q}.
\]
The ceiling gives an integer stopping rule. If $q=0$, one update suffices.
\end{remark}

\section{Frozen NTK convergence}

\begin{theorem}[Frozen NTK convergence to the target]
Let $K:E\to E$ be continuous and linear, fix $\eta\in\mathbb{R}$, a target $y\in E$, and an initial prediction $f_0\in E$. Suppose that for some $0\le q<1$,
\[
\|r-\eta Kr\|\le q\|r\|
\]
for every $r\in E$. Define
\[
r_0=f_0-y,\qquad r_{n+1}=r_n-\eta Kr_n,
\qquad f_n=y+r_n.
\]
Then
\[
\|f_n-y\|\le q^n\|f_0-y\|
\]
for every $n$, and $f_n\to y$.
\end{theorem}

\begin{proof}
Apply the geometric residual bound to $S(r)=r-\eta Kr$. Since $f_n-y=r_n$, the same estimate applies to prediction error. The strict inequality $q<1$ yields convergence.
\end{proof}

\begin{remark}[Nullspace obstruction]
If $v\ne0$ and $Kv=0$, then $(I-\eta K)v=v$ for every $\eta$. Therefore no global contraction factor $q<1$ exists. Positive semidefiniteness alone does not guarantee interpolation.
\end{remark}

\section{Exact spectral dynamics}

\begin{theorem}[Exact decay on an eigendirection]
Let $Kv=\lambda v$. Under $r_{n+1}=r_n-\eta Kr_n$ with $r_0=v$, one has
\[
r_n=(1-\eta\lambda)^n v
\]
for every $n\ge0$.
\end{theorem}

\begin{proof}
The formula is immediate at $n=0$. Assuming it at $n$, linearity and the eigenvector equation give
\begin{align*}
r_{n+1}
&=(1-\eta\lambda)^n v
-\eta K\bigl((1-\eta\lambda)^n v\bigr)\\
&=(1-\eta\lambda)^n(1-\eta\lambda)v.
\end{align*}
This is the desired formula at $n+1$.
\end{proof}

\begin{corollary}[Modewise stability]
A nonzero eigendirection converges to zero exactly when
\[
|1-\eta\lambda|<1.
\]
For $\lambda>0$, this is equivalent to $0<\eta\lambda<2$.
\end{corollary}

\begin{corollary}[Finite-dimensional spectral factor]
Suppose $K$ is self-adjoint on $\mathbb{R}^N$ with orthonormal eigenvectors $v_i$ and eigenvalues $\lambda_i$. If $r_0=\sum_i a_i v_i$, then
\[
r_n=\sum_{i=1}^N a_i(1-\eta\lambda_i)^n v_i,
\]
and
\[
\|I-\eta K\|_{\mathrm{op}}
=\max_{1\le i\le N}|1-\eta\lambda_i|.
\]
\end{corollary}

\begin{proof}
Apply the eigendirection theorem to every basis vector and use linearity. Orthogonal diagonalization identifies the Euclidean operator norm with the largest absolute diagonal factor.
\end{proof}

The factors classify behavior completely: a factor in $(-1,0)$ creates sign-alternating decay, a factor in $(0,1)$ monotone scalar decay, a factor of magnitude one persistence, and a factor of magnitude greater than one instability.

\section{Architecture universality}

\begin{theorem}[Universality for equal frozen kernels]
Consider two models with frozen kernels $K_1,K_2:E\to E$, the same learning rate $\eta$, target $y$, and initial prediction $f_0$. If $K_1=K_2$, then
\[
f_n^{(1)}=f_n^{(2)}
\]
for every $n\ge0$.
\end{theorem}

\begin{proof}
The initial residual is common, and equality of kernels makes the two update maps identical. Repeated application of the same map gives equal residuals; adding the common target gives equal predictions.
\end{proof}

Global operator equality is stronger than necessary. It suffices that the operators agree in action where training actually takes them.

\begin{theorem}[Pathwise kernel-action universality]
Let
\[
r_{n+1}^{(j)}=r_n^{(j)}-\eta K_jr_n^{(j)},
\qquad r_0^{(j)}=r_0,
\]
for $j\in\{1,2\}$. Suppose that at every step
\[
K_1r_n^{(1)}=K_2r_n^{(2)}.
\]
Then $r_n^{(1)}=r_n^{(2)}$ for every $n\ge0$.
\end{theorem}

\begin{proof}
Induct on $n$. The initial residuals agree. If the residuals agree at step $n$, then the assumed equality of kernel actions gives
\begin{align*}
r_{n+1}^{(1)}
&=r_n^{(1)}-\eta K_1r_n^{(1)}\\
&=r_n^{(2)}-\eta K_2r_n^{(2)}
=r_{n+1}^{(2)}.
\end{align*}
\end{proof}

\begin{remark}
These conclusions concern predictions on the selected training set. They do not imply equal parameters, internal representations, or predictions on arbitrary unseen inputs.
\end{remark}

\section{Tropical cell confinement}

\begin{theorem}[Tropical cell freezing]
Let $c:\mathbb{R}^P\to C$ assign cells and let $\mathcal K:\mathbb{R}^P\to\mathbb{R}^{N\times N}$ be cellwise constant. Let $\theta:[0,T)\to\mathbb{R}^P$ with $T>0$. If
\[
c(\theta(t))=c(\theta(0))
\]
for every $0\le t<T$, then
\[
\mathcal K(\theta(t))=\mathcal K(\theta(0))
\]
throughout the same interval.
\end{theorem}

\begin{proof}
For any $t\in[0,T)$, the two parameter points have the same cell label. Cellwise constancy therefore gives equality of their kernel matrices.
\end{proof}

This theorem separates geometry from analysis. Cell invariance freezes the kernel but does not guarantee stability. The contraction hypothesis guarantees interpolation for a frozen kernel but does not explain why the kernel remains fixed. Combining both produces the full lazy-training conclusion: certify a common cell, infer a constant kernel, estimate $\|I-\eta K\|_{\mathrm{op}}$, and apply the convergence theorem.

\section{Algorithms and numerical examples}

A direct simulator starts from $r_0=f_0-y$ and repeats $r\leftarrow r-\eta Kr$. For a dense $N\times N$ matrix and $m$ updates, this costs $O(mN^2)$ time. Storing every prediction costs $O(mN)$ space, whereas retaining only the final state costs $O(N)$ beyond the matrix.

For symmetric $K$, a spectral diagnostic computes eigenvalues $\lambda_i$ and
\[
q=\max_i|1-\eta\lambda_i|.
\]
Dense eigendecomposition costs $O(N^3)$. The value $q<1$ certifies Euclidean contraction; individual factors identify oscillation, persistence, and instability.

As an example, let
\[
K=\begin{pmatrix}1&0\\0&3\end{pmatrix},
\qquad \eta=\tfrac12,
\qquad r_0=\begin{pmatrix}2\\-1\end{pmatrix}.
\]
The factors are $1/2$ and $-1/2$, so
\[
r_n=\begin{pmatrix}2(1/2)^n\\-(-1/2)^n\end{pmatrix}.
\]
Both coordinates decay at magnitude rate $1/2$, while the second alternates sign. In contrast,
\[
K=\begin{pmatrix}1&0\\0&0\end{pmatrix}
\]
is positive semidefinite but leaves the second residual coordinate unchanged.

To test pathwise universality numerically, simulate both paths and monitor
\[
\|r_n^{(1)}-r_n^{(2)}\|
\quad\text{and}\quad
\|K_1r_n^{(1)}-K_2r_n^{(2)}\|.
\]
The theorem predicts exact equality when the second quantity vanishes at every step, up to floating-point error in a numerical implementation.

\section{Applications, limitations, and future work}

The spectral factors provide a learning-rate diagnostic and an estimate of the slowest mode. Kernel nullspaces identify target components inaccessible to frozen training. Equal-kernel and pathwise-action comparisons provide task-specific notions of architecture equivalence. In piecewise-linear models, a certified distance from the trajectory to every cell wall can potentially bound the duration for which the exact frozen analysis remains valid.

The theory does not establish generalization beyond the finite dataset, parameter convergence, or kernel freezing for an arbitrary network. Crossing a cell wall or gradual Jacobian drift creates a perturbed rather than exact recurrence. Likewise, changing the target, initialization, or learning rate can change trajectories even when kernels agree.

Natural extensions include a quantitative universality bound for approximately equal kernels, a necessary-and-sufficient spectral characterization of stable learning rates for positive-definite empirical kernels, a chamber-margin bound on the duration of tropical NTK stability, and a direct characterization of architecture classes through equality of parameter-Jacobian Gram operators.

\section{Conclusion}

Frozen NTK training reduces to repeated application of $I-\eta K$. Strict contraction yields
\[
\|r_n\|\le q^n\|r_0\|
\]
and convergence to the target. Eigenvectors evolve exactly by $(1-\eta\lambda)^n$. Equal kernels yield identical trajectories, while equality only of kernel actions along realized paths already suffices. Cell confinement supplies an exact geometric certificate of kernel constancy. In this architecture-independent picture, geometry freezes the kernel, spectrum determines rates, contraction guarantees interpolation, and kernel action determines the training trajectory.

\end{document}

