from __future__ import annotations
from typing import List, Tuple

def spectral_modes(eta: float, eigenvalues: List[float], steps: int) -> List[Tuple[float, List[float]]]:
    """Return each eigenvalue and its factors through the requested horizon."""
    return [(lam, [(1.0 - eta * lam) ** n for n in range(steps + 1)])
            for lam in eigenvalues]

if __name__ == "__main__":
    for eigenvalue, values in spectral_modes(0.5, [0.0, 1.0, 3.0, 5.0], 6):
        print(f"lambda={eigenvalue}: {values}")

